const body = $input.first().json.body || $input.first().json;
const cluster = body.segmento_cluster ?? 1;
const demanda = Number(body.demanda_optimizada_moe_m_cop ?? body.demanda_optimizada_moe ?? 0);
const alta = cluster === 0 || cluster === 2 || demanda >= 15;
return [{
  json: {
    ok: true,
    workflow: 'greensight-ml-alert',
    prioridad: alta ? 'ALTA' : 'ESTANDAR',
    segmento_cluster: cluster,
    demanda_optimizada_moe_m_cop: demanda,
    recomendacion: body.recomendacion_producto || 'Seguimiento comercial Green Services',
    procesadoEn: new Date().toISOString()
  }
}];
